import sys

def resolve_type(t, definitions):
    while t in definitions:
        t = definitions[t]
        if t == 'void' or t == 'errtype':
            break
        if t.startswith('&'):
            if t[1:] == 'void' or t[1:] == 'errtype':
                t = 'errtype'
                break
        elif t.endswith('*'):
            if t[:-1] == 'void' or t[:-1] == 'errtype':
                t = 'errtype'
                break
    return t

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    operators = input[1:]
    definitions = {}
    results = []

    for operator in operators:
        if operator.startswith('typedef'):
            _, a, b = operator.split()
            resolved_a = resolve_type(a, definitions)
            definitions[b] = resolved_a
        elif operator.startswith('typeof'):
            _, a = operator.split()
            resolved_a = resolve_type(a, definitions)
            if resolved_a == 'void' or resolved_a == 'errtype':
                final_type = resolved_a
            else:
                count_asterisks = resolved_a.count('*')
                final_type = 'void' + '*' * count_asterisks
            results.append(final_type)

    for result in results:
        print(result)

main()
